 5→ * across the web UI. Normalizes @ prefixes, detects reference types, and generates
 6→ * navigation URLs.
 7→ *
 8→ * AC: @ui-reference-display ac-1
 9→ */
10→
11→/** Types of entities that can be referenced in the UI. */
12→export type RefType = 'task' | 'spec' | 'plan' | 'session';
13→
14→/**
15→ * Strip the leading @ from a reference string if present.
16→ * Prevents double @@ when displaying with @ prefix.
17→ */
18→export function normalizeRef(ref: string): string {
19→	return ref.startsWith('@') ? ref.slice(1) : ref;
20→}
21→
22→/** ULID pattern: 26 Crockford base32 characters (digits 0-9 + A-Z excluding I, L, O, U). */
23→const ULID_RE = /^[0-9A-HJKMNP-TV-Z]{26}$/i;
24→
25→/**
26→ * Check whether a normalized ref looks like a ULID.
27→ */
28→export function isUlid(ref: string): boolean {
29→	return ULID_RE.test(normalizeRef(ref));
30→}
31→
32→/**
33→ * Get a short display version of a reference.
34→ * ULIDs are truncated to 8 chars; slugs are returned in full.
35→ */
36→export function shortRef(ref: string): string {
37→	const norm = normalizeRef(ref);
38→	return isUlid(norm) ? norm.slice(0, 8) : norm;
39→}
40→
