43→ * @param basePath - The SvelteKit base path (from $app/paths). Defaults to ''.
44→ */
45→export function refHref(type: RefType, ref: string, basePath = ''): string {
46→	const encoded = encodeURIComponent(ref);
47→	switch (type) {
48→		case 'task':
49→			return `${basePath}/tasks/board?ref=${encoded}`;
50→		case 'spec':
51→			return `${basePath}/specs?ref=${encoded}`;
52→		case 'plan':
53→			return `${basePath}/plans?ref=${encoded}`;
54→		case 'session':
55→			return `${basePath}/sessions/${normalizeRef(ref)}`;
56→	}
57→}
